style.css:
@-moz-document domain("roblox.com") {
/* Main background - black */
    body, html {
        background: #000000 !important;
        background-image: none !important;
        color: #ffffff !important;
    }
    
    /* Header styling - black with red border */
    header, #navigation, .navbar, [class*="Navigation"] {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
        border-bottom: 3px solid #ff0000 !important;
    }
    
    /* All containers and content areas - black with red borders */
    .container, .container-main, [class*="container"], 
    [class*="Container"], main, #content, .content {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
        padding: 10px !important;
        color: #ffffff !important;
    }
    
    /* Panels and cards - black with red borders */
    .panel, .card, [class*="panel"], [class*="Card"],
    .section, [class*="Section"], .item-card, [class*="item-card"] {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
        border-radius: 0 !important;
        color: #ffffff !important;
        margin: 5px !important;
    }
    
    /* Buttons - black background, red border */
    button, .btn, [class*="Button"], input[type="submit"], 
    input[type="button"], a.btn {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
        border-radius: 0 !important;
        color: #ffffff !important;
        font-weight: bold !important;
        text-shadow: none !important;
        padding: 6px 12px !important;
        box-shadow: none !important;
    }
    
    button:hover, .btn:hover, [class*="Button"]:hover {
        background: #1a0000 !important;
        border-color: #ff3333 !important;
    }
    
    button:active, .btn:active, [class*="Button"]:active {
        background: #330000 !important;
    }
    
    /* Input fields - black with red border */
    input[type="text"], input[type="password"], input[type="email"],
    textarea, select, [class*="Input"], [class*="input"] {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
        border-radius: 0 !important;
        color: #ffffff !important;
        padding: 4px !important;
    }
    
    /* Navigation links - white/red */
    .nav-link, [class*="NavLink"], a {
        color: #ffffff !important;
        text-decoration: none !important;
    }
    
    .nav-link:hover, [class*="NavLink"]:hover, a:hover {
        color: #ff0000 !important;
    }
    
    /* Remove modern effects */
    * {
        border-radius: 0 !important;
        box-shadow: none !important;
        text-shadow: none !important;
    }
    
    /* Title bars - black with red text */
    h1, h2, h3, h4, h5, h6, [class*="Title"], [class*="Heading"] {
        background: #000000 !important;
        color: #ff0000 !important;
        font-weight: bold !important;
        padding: 6px 8px !important;
        border: 2px solid #ff0000 !important;
        border-bottom: 3px solid #ff0000 !important;
        margin-bottom: 10px !important;
    }
    
    /* Sidebar/menu styling */
    aside, .sidebar, [class*="Sidebar"], nav {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
    }
    
    /* Game thumbnails and images */
    img {
        border: 2px solid #ff0000 !important;
    }
    
    /* Scrollbars - black and red */
    ::-webkit-scrollbar {
        width: 12px !important;
        height: 12px !important;
        background: #000000 !important;
    }
    
    ::-webkit-scrollbar-track {
        background: #000000 !important;
        border: 1px solid #ff0000 !important;
    }
    
    ::-webkit-scrollbar-thumb {
        background: #ff0000 !important;
        border: 1px solid #000000 !important;
    }
    
    ::-webkit-scrollbar-thumb:hover {
        background: #ff3333 !important;
    }
    
    ::-webkit-scrollbar-corner {
        background: #000000 !important;
    }
    
    /* Footer */
    footer {
        background: #000000 !important;
        border-top: 2px solid #ff0000 !important;
        color: #ffffff !important;
    }
    
    /* Modal/popup windows */
    .modal, [class*="Modal"], .popup, [class*="Popup"],
    .modal-content, [class*="modal-content"] {
        background: #000000 !important;
        border: 3px solid #ff0000 !important;
        color: #ffffff !important;
    }
    
    /* Dividers and separators */
    hr, .divider, [class*="Divider"] {
        border-color: #ff0000 !important;
        background: #ff0000 !important;
    }
    
    /* Tables */
    table, th, td {
        background: #000000 !important;
        border: 1px solid #ff0000 !important;
        color: #ffffff !important;
    }
    
    /* Lists */
    ul, ol, li {
        color: #ffffff !important;
    }
    
    /* Text elements */
    p, span, div, label {
        color: #ffffff !important;
    }
    
    /* Status bar / info bars */
    [class*="status"], [class*="Status"], [class*="info"], [class*="Info"] {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
        color: #ffffff !important;
    }
    
    /* Badges and tags */
    .badge, [class*="Badge"], .tag, [class*="Tag"] {
        background: #000000 !important;
        border: 1px solid #ff0000 !important;
        color: #ff0000 !important;
    }
    
    /* Dropdowns and menus */
    .dropdown, [class*="Dropdown"], .menu, [class*="Menu"] {
        background: #000000 !important;
        border: 2px solid #ff0000 !important;
    }
    
    /* Selected/active states */
    .active, [class*="active"], .selected, [class*="Selected"] {
        background: #330000 !important;
        border-color: #ff0000 !important;
        color: #ff0000 !important;
    }
}
